 line(270,220,270,490,'#59707c',7);
 line(630,220,630,490,'#59707c',7);
 line(260,217,642,217,'#72818b',12);
 line(292,411,608,411,'#46515b',10);
 line(310,415,310,478,'#46515b',6);
 line(590,415,590,478,'#46515b',6);
 line(700,227,700,493,'#5e707a',5);
 g.fillStyle='#a4b8bf';g.fillRect(679,235,42,48);
 // Pictogram, not additional on-screen words.
 g.fillStyle='#243a49';g.fillRect(688,246,24,20);
 ellipse(692,269,3,3,'#243a49');ellipse(708,269,3,3,'#243a49');
