 g.beginPath();g.moveTo(-112,0);
 g.bezierCurveTo(-87,-105,82,-105,112,0);
 g.quadraticCurveTo(83,-14,56,0);
 g.quadraticCurveTo(28,-14,0,0);
 g.quadraticCurveTo(-28,-14,-56,0);
 g.quadraticCurveTo(-84,-14,-112,0);
 g.fillStyle='#080d14';g.fill();g.strokeStyle='#354453';g.lineWidth=2;g.stroke();
