 ellipse(0,-195,25,31,man?'#89908e':'#c5ced4');
 ellipse(0,-190,19,26,'#c8a18b');
 if(back){
  ellipse(0,-196,25,30,man?'#838985':'#c7d0d6');
  if(!man)g.fillStyle='#c7d0d6',g.fillRect(-25,-195,50,25);
 }else{
  if(man){
   poly([[-20,-191],[-15,-170],[0,-158],[17,-171],[20,-192],
         [10,-180],[-8,-180]],'#a7aaa6');
   ellipse(0,-217,20,8,'#8c938f');
  }else{
   poly([[-25,-204],[-20,-220],[4,-226],[23,-211],
