 if(running){
  running=false;if(audio)await audio.suspend();
  if('speechSynthesis'in window)speechSynthesis.cancel();
  title();this.textContent='Play Walk Anyway';return
 }
 if(!audio)initSound();else await audio.resume();
 if('speechSynthesis'in window)speechSynthesis.cancel();
